    public boolean mergeTriplets(int[][] triplets, int[] target) {
        int matchedMask = 0;

        for (int[] triplet : triplets) {
            if (triplet[0] > target[0] || triplet[1] > target[1] || triplet[2] > target[2]) {
                continue;
            }
            if (triplet[0] == target[0]) {
                matchedMask |= 1;
            }
            if (triplet[1] == target[1]) {
                matchedMask |= 2;
            }
            if (triplet[2] == target[2]) {
                matchedMask |= 4;
            }
            if (matchedMask == 7) {
                return true;
            }
        }

        return false;
    }
}

class Solution {
    public boolean mergeTriplets(int[][] triplets, int[] target) {
        int[] merged = new int[3];

        for (int[] triplet : triplets) {
            if (triplet[0] > target[0] || triplet[1] > target[1] || triplet[2] > target[2]) {
                continue;
            }
            for (int i = 0; i < 3; i++) {
                merged[i] = Math.max(merged[i], triplet[i]);
            }
        }

        return merged[0] == target[0]
                && merged[1] == target[1]
                && merged[2] == target[2];
    }
}

class Solution {
    public boolean mergeTriplets(int[][] triplets, int[] target) {
        for (int coordinate = 0; coordinate < 3; coordinate++) {
            boolean hasWitness = false;
            for (int[] triplet : triplets) {
                if (isSafe(triplet, target) && triplet[coordinate] == target[coordinate]) {
                    hasWitness = true;
                    break;
                }
            }
            if (!hasWitness) {
                return false;
            }
        }
        return true;
    }

    private boolean isSafe(int[] triplet, int[] target) {
        return triplet[0] <= target[0]
                && triplet[1] <= target[1]
                && triplet[2] <= target[2];
    }
}

class Solution {
    public boolean mergeTriplets(int[][] triplets, int[] target) {
        int[][] witnesses = new int[3][];

        for (int[] triplet : triplets) {
            if (triplet[0] > target[0] || triplet[1] > target[1] || triplet[2] > target[2]) {
                continue;
            }
            for (int coordinate = 0; coordinate < 3; coordinate++) {
                if (triplet[coordinate] == target[coordinate] && witnesses[coordinate] == null) {
                    witnesses[coordinate] = triplet;
                }
            }
        }

        int[] merged = new int[3];
        for (int coordinate = 0; coordinate < 3; coordinate++) {
            if (witnesses[coordinate] == null) {
                return false;
            }
            for (int i = 0; i < 3; i++) {
                merged[i] = Math.max(merged[i], witnesses[coordinate][i]);
            }
        }

        return merged[0] == target[0]
                && merged[1] == target[1]
                && merged[2] == target[2];
    }
}
